#[derive(Debug, Clone, PartialEq)]
pub enum Token {
    LBrace,
    RBrace,
    LBracket,
    RBracket,
    Colon,
    Comma,
    Null,
    True,
    False,
    Num(f64),
    Str(String),
}

#[derive(Debug, Clone, PartialEq)]
pub struct ParseError {
    pub pos: usize,
    pub msg: String,
}

impl fmt::Display for ParseError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        write!(f, "{} at character {}", self.msg, self.pos)
    }
}

impl std::error::Error for ParseError {}

pub struct Lexer {
    src: Vec<char>,
    pos: usize,
}

impl Lexer {
    pub fn new(input: &str) -> Lexer {
        Lexer { src: input.chars().collect(), pos: 0 }
    }

    pub fn pos(&self) -> usize {
        self.pos
    }

    fn peek(&self) -> Option<char> {
        self.src.get(self.pos).copied()
    }

    fn bump(&mut self) -> Option<char> {
        let c = self.peek();
        if c.is_some() {
            self.pos += 1;
        }
        c
    }

    fn err<T>(&self, msg: &str) -> Result<T, ParseError> {
        Err(ParseError { pos: self.pos, msg: msg.to_string() })
    }

    fn skip_ws(&mut self) {
        while matches!(self.peek(), Some(' ') | Some('\t') | Some('\n') | Some('\r')) {
            self.pos += 1;
        }
    }

    fn keyword(&mut self, word: &str, tok: Token) -> Result<Token, ParseError> {
        for want in word.chars() {
            if self.bump() != Some(want) {
                return self.err(&format!("expected `{word}`"));
            }
        }
        Ok(tok)
    }

    pub fn next_token(&mut self) -> Result<Option<Token>, ParseError> {
        self.skip_ws();
        let c = match self.peek() {
            Some(c) => c,
            None => return Ok(None),
        };
        let tok = match c {
            '{' => { self.pos += 1; Token::LBrace }
            '}' => { self.pos += 1; Token::RBrace }
            other => return self.err(&format!("unexpected character `{other}`")),
        };
        tok
    }
}

pub fn tokenize(input: &str) -> Result<Vec<Token>, ParseError> {
    let mut lex = Lexer::new(input);
    let mut out = Vec::new();
    while let Some(t) = lex.next_token()? {
        out.push(t);
    }
    Ok(out)
}

