        assert_eq!(
            tokenize(r#""A❤""#).unwrap(),
            vec![Token::Str("A\u{2764}".to_string())]
        );
    }

    #[test]
    fn broken_strings_are_errors_not_panics() {
        assert!(tokenize(r#""no end"#).is_err());
        assert!(tokenize(r#""\q""#).is_err());
        assert!(tokenize(r#""\u00ZZ""#).is_err());
        assert!(tokenize(r#""\u12""#).is_err());
    }
