#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn a_flat_array() {
        assert_eq!(
            parse("[1, true, null]"),
            Ok(Value::Array(vec![
                Value::Number(1.0),
                Value::Bool(true),
                Value::Null,
            ]))
        );
    }

    #[test]
    fn the_empty_array() {
        assert_eq!(parse("[]"), Ok(Value::Array(Vec::new())));
        assert_eq!(parse("[ ]"), Ok(Value::Array(Vec::new())));
    }

    #[test]
    fn nesting_is_free() {
        let v = parse("[[1, [2]], [], [[[3]]]]").unwrap();
        println!("{v:?}");
        assert_eq!(v.count(), 10);
        assert_eq!(v.type_name(), "array");
    }

    #[test]
    fn malformed_arrays_are_errors() {
        assert!(parse("[1,]").is_err());
        assert!(parse("[1 2]").is_err());
        assert!(parse("[1").is_err());
    }
}

