    "scale": 1.5e3,
    "tags": ["rust", "crab", []],
    "meta": { "active": true, "parent": null },
    "id": 43
}"#;

pub fn demo() -> String {
    match parse(DOC) {
        Ok(v) => v.to_string(),
        Err(e) => format!("error: {e}"),
    }
}

